  ((select id from sites where code = 'PA-BERNINI'), '2025-11-05', 'Inaugurazione Palermo Bernini', 'Apertura del 12° store cittadino, quarto diretto. 21 dipendenti, età media 34 anni. All''epoca la rete regionale era indicata in 88 pdv.'),
  ((select id from sites where code = 'ME-GALATI'), '2026-03-25', 'Apertura Galati', 'Punto vendita affiliato con Gruppo Manna. Macelleria e gastronomia take away, pane sfuso. 19 addetti.'),
  ((select id from sites where code = 'ME-SANTAGATA'), '2026-08-01', 'Apertura Sant''Agata di Militello', 'Store affiliato di circa 1.100 mq, 21 risorse, età media 38 anni. Rete regionale oltre i 90 punti vendita.'),
  ((select id from sites where code = 'EN-PIAZZA'), '2019-06-26', 'Riapertura Piazza Armerina', 'Primo dei 21 ex Uno Discount / Abate riaperti da MD tra giugno e luglio 2019.');
